package com.orderflow.product; import com.orderflow.contracts.*; import org.springframework.kafka.annotation.KafkaListener; import org.springframework.kafka.core.KafkaTemplate; import org.springframework.stereotype.Component; import java.time.Instant; import java.util.UUID;
@Component public class ProductListener { private final ProductValidationRepository repo; private final KafkaTemplate<String,Object> kafka; public ProductListener(ProductValidationRepository r,KafkaTemplate<String,Object> k){repo=r;kafka=k;} @KafkaListener(topics=Topics.PRODUCT,groupId="product-validation") public void handle(SagaEvent e){ boolean ok=e.payload().products().stream().allMatch(p->p.code()!=null&&!p.code().isBlank()&&p.quantity()>0&&p.unitValue()!=null&&p.unitValue().signum()>0); ProductValidation v=new ProductValidation();v.orderId=e.orderId();v.status=ok?"VALID":"INVALID";repo.save(v); SagaEvent out=new SagaEvent(UUID.randomUUID().toString(),e.transactionId(),e.orderId(),SagaStep.PRODUCT_VALIDATION,ok?SagaStatus.SUCCESS:SagaStatus.FAILED,ok?"Products validated":"Invalid product",e.payload(),Instant.now());kafka.send(Topics.ORCHESTRATOR,e.orderId(),out);} }
